-- M12b: RFI (Request for Information) (ticket 0154).
--
-- Per-project RFIs raised by engineers against internal or external parties.
-- RFI number is generated by the M33 numbering scheme (key: 'RFI') when one
-- exists; service layer falls back to sequential integer if none is defined.

create table public.rfis (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null default public.current_tenant_id() references public.tenants (id),
  project_id uuid not null references public.projects (id),
  rfi_number text not null,
  raised_by uuid references public.app_users (id),
  -- Can be directed at an internal user OR an external CRM contact (not both).
  addressed_to_user_id uuid references public.app_users (id),
  addressed_to_contact_id uuid references public.contacts (id),
  subject text not null,
  description text,
  date_raised date not null default current_date,
  date_required date,
  date_responded date,
  response text,
  status text not null default 'open'
    check (status in ('open', 'responded', 'closed', 'cancelled')),
  reference_document_ids uuid[] not null default '{}',
  created_at timestamptz not null default now(),
  -- rfi_number is unique within a project for a tenant
  unique (tenant_id, project_id, rfi_number)
);

alter table public.rfis enable row level security;

create policy "rfis_tenant_isolation" on public.rfis
  for all
  using (tenant_id = public.current_tenant_id())
  with check (tenant_id = public.current_tenant_id());

create index rfis_project_id_idx on public.rfis (project_id);
create index rfis_status_idx on public.rfis (status);
create index rfis_date_required_idx on public.rfis (date_required);

insert into public.permissions (id, description) values
  ('engineering.rfi.manage', 'Create, respond to, or close an RFI');

insert into public.role_permissions (role_id, permission_id) values
  ('role.platform_administrator',  'engineering.rfi.manage'),
  ('role.architect_lead',          'engineering.rfi.manage'),
  ('role.project_engineer_lead',   'engineering.rfi.manage'),
  ('role.structural_designer',     'engineering.rfi.manage'),
  ('role.site_civil_engineer',     'engineering.rfi.manage'),
  ('role.site_mep_engineer',       'engineering.rfi.manage');
